var WrapInRectangle = require('../../src/actions/WrapInRectangle');

describe('Phaser.Actions.WrapInRectangle', function ()
{
    var rect;

    beforeEach(function ()
    {
        rect = { left: 0, right: 100, top: 0, bottom: 100 };
    });

    it('should return the items array', function ()
    {
        var items = [];
        var result = WrapInRectangle(items, rect);
        expect(result).toBe(items);
    });

    it('should return an empty array unchanged', function ()
    {
        var items = [];
        var result = WrapInRectangle(items, rect);
        expect(result).toEqual([]);
    });

    it('should leave coordinates inside the rectangle unchanged', function ()
    {
        var items = [{ x: 50, y: 50 }];
        WrapInRectangle(items, rect);
        expect(items[0].x).toBe(50);
        expect(items[0].y).toBe(50);
    });

    it('should wrap x when it equals rect.right', function ()
    {
        var items = [{ x: 100, y: 50 }];
        WrapInRectangle(items, rect);
        expect(items[0].x).toBe(0);
    });

    it('should wrap y when it equals rect.bottom', function ()
    {
        var items = [{ x: 50, y: 100 }];
        WrapInRectangle(items, rect);
        expect(items[0].y).toBe(0);
    });

    it('should wrap x when it is less than rect.left', function ()
    {
        var items = [{ x: -10, y: 50 }];
        WrapInRectangle(items, rect);
        expect(items[0].x).toBeCloseTo(90);
    });

    it('should wrap x when it exceeds rect.right', function ()
    {
        var items = [{ x: 110, y: 50 }];
        WrapInRectangle(items, rect);
        expect(items[0].x).toBeCloseTo(10);
    });

    it('should wrap y when it is less than rect.top', function ()
    {
        var items = [{ x: 50, y: -10 }];
        WrapInRectangle(items, rect);
        expect(items[0].y).toBeCloseTo(90);
    });

    it('should wrap y when it exceeds rect.bottom', function ()
    {
        var items = [{ x: 50, y: 110 }];
        WrapInRectangle(items, rect);
        expect(items[0].y).toBeCloseTo(10);
    });

    it('should default padding to 0 when not provided', function ()
    {
        var items = [{ x: 100, y: 100 }];
        WrapInRectangle(items, rect);
        expect(items[0].x).toBe(0);
        expect(items[0].y).toBe(0);
    });

    it('should apply padding to expand the wrap boundary', function ()
    {
        var items = [{ x: -5, y: 50 }];
        WrapInRectangle(items, rect, 10);
        expect(items[0].x).toBe(-5);
        expect(items[0].y).toBe(50);
    });

    it('should wrap x accounting for padding on the left', function ()
    {
        // range is [left-padding, right+padding) = [-10, 110), width = 120
        // Wrap(-15, -10, 110) = -10 + 115 = 105
        var items = [{ x: -15, y: 50 }];
        WrapInRectangle(items, rect, 10);
        expect(items[0].x).toBeCloseTo(105);
    });

    it('should wrap x accounting for padding on the right', function ()
    {
        // Wrap(115, -10, 110) = -10 + 5 = -5
        var items = [{ x: 115, y: 50 }];
        WrapInRectangle(items, rect, 10);
        expect(items[0].x).toBeCloseTo(-5);
    });

    it('should wrap y accounting for padding on the top', function ()
    {
        // Wrap(-15, -10, 110) = 105
        var items = [{ x: 50, y: -15 }];
        WrapInRectangle(items, rect, 10);
        expect(items[0].y).toBeCloseTo(105);
    });

    it('should wrap y accounting for padding on the bottom', function ()
    {
        // Wrap(115, -10, 110) = -5
        var items = [{ x: 50, y: 115 }];
        WrapInRectangle(items, rect, 10);
        expect(items[0].y).toBeCloseTo(-5);
    });

    it('should process all items in the array', function ()
    {
        var items = [
            { x: -10, y: 50 },
            { x: 50, y: -10 },
            { x: 110, y: 110 }
        ];
        WrapInRectangle(items, rect);
        expect(items[0].x).toBeCloseTo(90);
        expect(items[1].y).toBeCloseTo(90);
        expect(items[2].x).toBeCloseTo(10);
        expect(items[2].y).toBeCloseTo(10);
    });

    it('should mutate items in place', function ()
    {
        var item = { x: 150, y: 150 };
        var items = [item];
        WrapInRectangle(items, rect);
        expect(item.x).toBeCloseTo(50);
        expect(item.y).toBeCloseTo(50);
    });

    it('should work with a non-zero-origin rectangle', function ()
    {
        var offsetRect = { left: 50, right: 150, top: 50, bottom: 150 };
        var items = [{ x: 40, y: 160 }];
        WrapInRectangle(items, offsetRect);
        expect(items[0].x).toBeCloseTo(140);
        expect(items[0].y).toBeCloseTo(60);
    });

    it('should handle zero padding explicitly', function ()
    {
        var items = [{ x: 100, y: 100 }];
        WrapInRectangle(items, rect, 0);
        expect(items[0].x).toBe(0);
        expect(items[0].y).toBe(0);
    });
});

var PlaceOnCircle = require('../../src/actions/PlaceOnCircle');

describe('Phaser.Actions.PlaceOnCircle', function ()
{
    var circle;
    var items;

    beforeEach(function ()
    {
        circle = { x: 0, y: 0, radius: 100 };
        items = [];
        for (var i = 0; i < 4; i++)
        {
            items.push({ x: 0, y: 0 });
        }
    });

    it('should return the items array', function ()
    {
        var result = PlaceOnCircle(items, circle);
        expect(result).toBe(items);
    });

    it('should position items evenly around the circle with default angles', function ()
    {
        PlaceOnCircle(items, circle);
        var angleStep = 6.28 / items.length;

        for (var i = 0; i < items.length; i++)
        {
            var angle = i * angleStep;
            expect(items[i].x).toBeCloseTo(circle.radius * Math.cos(angle), 5);
            expect(items[i].y).toBeCloseTo(circle.radius * Math.sin(angle), 5);
        }
    });

    it('should use the circle center as the origin', function ()
    {
        circle.x = 200;
        circle.y = 300;
        PlaceOnCircle(items, circle);

        for (var i = 0; i < items.length; i++)
        {
            var dx = items[i].x - circle.x;
            var dy = items[i].y - circle.y;
            var dist = Math.sqrt(dx * dx + dy * dy);
            expect(dist).toBeCloseTo(circle.radius, 5);
        }
    });

    it('should use the circle radius', function ()
    {
        circle.radius = 50;
        PlaceOnCircle(items, circle);

        for (var i = 0; i < items.length; i++)
        {
            var dx = items[i].x - circle.x;
            var dy = items[i].y - circle.y;
            var dist = Math.sqrt(dx * dx + dy * dy);
            expect(dist).toBeCloseTo(50, 5);
        }
    });

    it('should respect a custom startAngle', function ()
    {
        var startAngle = Math.PI / 2;
        PlaceOnCircle(items, circle, startAngle);

        expect(items[0].x).toBeCloseTo(circle.radius * Math.cos(startAngle), 5);
        expect(items[0].y).toBeCloseTo(circle.radius * Math.sin(startAngle), 5);
    });

    it('should respect a custom endAngle', function ()
    {
        var startAngle = 0;
        var endAngle = Math.PI;
        PlaceOnCircle(items, circle, startAngle, endAngle);

        var angleStep = (endAngle - startAngle) / items.length;

        for (var i = 0; i < items.length; i++)
        {
            var angle = startAngle + i * angleStep;
            expect(items[i].x).toBeCloseTo(circle.radius * Math.cos(angle), 5);
            expect(items[i].y).toBeCloseTo(circle.radius * Math.sin(angle), 5);
        }
    });

    it('should place a single item at the startAngle', function ()
    {
        var single = [{ x: 0, y: 0 }];
        PlaceOnCircle(single, circle, 0, 6.28);

        expect(single[0].x).toBeCloseTo(circle.radius * Math.cos(0), 5);
        expect(single[0].y).toBeCloseTo(circle.radius * Math.sin(0), 5);
    });

    it('should handle a circle with zero radius', function ()
    {
        circle.radius = 0;
        PlaceOnCircle(items, circle);

        for (var i = 0; i < items.length; i++)
        {
            expect(items[i].x).toBeCloseTo(circle.x, 5);
            expect(items[i].y).toBeCloseTo(circle.y, 5);
        }
    });

    it('should handle startAngle equal to endAngle', function ()
    {
        var angle = Math.PI / 4;
        PlaceOnCircle(items, circle, angle, angle);

        for (var i = 0; i < items.length; i++)
        {
            expect(items[i].x).toBeCloseTo(circle.radius * Math.cos(angle), 5);
            expect(items[i].y).toBeCloseTo(circle.radius * Math.sin(angle), 5);
        }
    });

    it('should handle negative startAngle', function ()
    {
        var startAngle = -Math.PI;
        PlaceOnCircle(items, circle, startAngle, 0);

        var angleStep = (0 - startAngle) / items.length;

        for (var i = 0; i < items.length; i++)
        {
            var angle = startAngle + i * angleStep;
            expect(items[i].x).toBeCloseTo(circle.radius * Math.cos(angle), 5);
            expect(items[i].y).toBeCloseTo(circle.radius * Math.sin(angle), 5);
        }
    });

    it('should distribute items across a partial arc', function ()
    {
        var startAngle = 0;
        var endAngle = Math.PI / 2;
        PlaceOnCircle(items, circle, startAngle, endAngle);

        var angleStep = (endAngle - startAngle) / items.length;

        expect(items[0].x).toBeCloseTo(circle.radius * Math.cos(0), 5);
        expect(items[0].y).toBeCloseTo(circle.radius * Math.sin(0), 5);

        expect(items[items.length - 1].x).toBeCloseTo(circle.radius * Math.cos((items.length - 1) * angleStep), 5);
        expect(items[items.length - 1].y).toBeCloseTo(circle.radius * Math.sin((items.length - 1) * angleStep), 5);
    });

    it('should not modify items beyond x and y', function ()
    {
        var itemsWithExtra = [
            { x: 0, y: 0, name: 'a' },
            { x: 0, y: 0, name: 'b' }
        ];
        PlaceOnCircle(itemsWithExtra, circle);

        expect(itemsWithExtra[0].name).toBe('a');
        expect(itemsWithExtra[1].name).toBe('b');
    });

    it('should return an empty array when given an empty array', function ()
    {
        var result = PlaceOnCircle([], circle);
        expect(result).toEqual([]);
    });
});

var RandomCircle = require('../../src/actions/RandomCircle');

describe('Phaser.Actions.RandomCircle', function ()
{
    var circle;
    var items;

    beforeEach(function ()
    {
        circle = { x: 0, y: 0, radius: 100 };
        items = [];
    });

    it('should return the items array', function ()
    {
        var result = RandomCircle(items, circle);

        expect(result).toBe(items);
    });

    it('should return an empty array when given an empty array', function ()
    {
        var result = RandomCircle([], circle);

        expect(result).toEqual([]);
    });

    it('should set x and y on each item', function ()
    {
        var item = { x: 0, y: 0 };
        items.push(item);

        RandomCircle(items, circle);

        expect(typeof item.x).toBe('number');
        expect(typeof item.y).toBe('number');
    });

    it('should position items within the circle radius', function ()
    {
        for (var i = 0; i < 20; i++)
        {
            items.push({ x: 0, y: 0 });
        }

        RandomCircle(items, circle);

        for (var j = 0; j < items.length; j++)
        {
            var dx = items[j].x - circle.x;
            var dy = items[j].y - circle.y;
            var dist = Math.sqrt(dx * dx + dy * dy);

            expect(dist).toBeLessThanOrEqual(circle.radius + 0.0001);
        }
    });

    it('should position items relative to circle center', function ()
    {
        circle = { x: 200, y: 300, radius: 50 };

        for (var i = 0; i < 20; i++)
        {
            items.push({ x: 0, y: 0 });
        }

        RandomCircle(items, circle);

        for (var j = 0; j < items.length; j++)
        {
            var dx = items[j].x - circle.x;
            var dy = items[j].y - circle.y;
            var dist = Math.sqrt(dx * dx + dy * dy);

            expect(dist).toBeLessThanOrEqual(circle.radius + 0.0001);
        }
    });

    it('should set all items within a zero-radius circle to the circle center', function ()
    {
        circle = { x: 50, y: 75, radius: 0 };
        items = [{ x: 0, y: 0 }, { x: 0, y: 0 }, { x: 0, y: 0 }];

        RandomCircle(items, circle);

        for (var i = 0; i < items.length; i++)
        {
            expect(items[i].x).toBeCloseTo(circle.x, 5);
            expect(items[i].y).toBeCloseTo(circle.y, 5);
        }
    });

    it('should process multiple items', function ()
    {
        var count = 10;

        for (var i = 0; i < count; i++)
        {
            items.push({ x: 0, y: 0 });
        }

        RandomCircle(items, circle);

        expect(items.length).toBe(count);

        for (var j = 0; j < items.length; j++)
        {
            expect(typeof items[j].x).toBe('number');
            expect(typeof items[j].y).toBe('number');
        }
    });

    it('should not produce all identical positions across many items', function ()
    {
        circle = { x: 0, y: 0, radius: 100 };

        for (var i = 0; i < 50; i++)
        {
            items.push({ x: 0, y: 0 });
        }

        RandomCircle(items, circle);

        var allSame = true;
        var firstX = items[0].x;
        var firstY = items[0].y;

        for (var j = 1; j < items.length; j++)
        {
            if (items[j].x !== firstX || items[j].y !== firstY)
            {
                allSame = false;
                break;
            }
        }

        expect(allSame).toBe(false);
    });

    it('should work with a large radius', function ()
    {
        circle = { x: 0, y: 0, radius: 10000 };

        for (var i = 0; i < 10; i++)
        {
            items.push({ x: 0, y: 0 });
        }

        RandomCircle(items, circle);

        for (var j = 0; j < items.length; j++)
        {
            var dx = items[j].x - circle.x;
            var dy = items[j].y - circle.y;
            var dist = Math.sqrt(dx * dx + dy * dy);

            expect(dist).toBeLessThanOrEqual(circle.radius + 0.0001);
        }
    });

    it('should work with negative circle center coordinates', function ()
    {
        circle = { x: -500, y: -300, radius: 100 };

        for (var i = 0; i < 10; i++)
        {
            items.push({ x: 0, y: 0 });
        }

        RandomCircle(items, circle);

        for (var j = 0; j < items.length; j++)
        {
            var dx = items[j].x - circle.x;
            var dy = items[j].y - circle.y;
            var dist = Math.sqrt(dx * dx + dy * dy);

            expect(dist).toBeLessThanOrEqual(circle.radius + 0.0001);
        }
    });
});

