                bindRenderbuffer: function () {},
                bindTexture: function () {},
                blendFunc: function () {},
                bufferData: function () {},
                clear: function () {},
                clearColor: function () {},
                compileShader: function () {},
                deleteBuffer: function () {},
                deleteFramebuffer: function () {},
                deleteProgram: function () {},
