        expect(result[0].y).toBe(-40);
        expect(result[1].x).toBe(-10);
        expect(result[1].y).toBe(-40);
        expect(result[2].x).toBe(-10);
        expect(result[2].y).toBe(-5);
        expect(result[3].x).toBe(-50);
        expect(result[3].y).toBe(-5);
    });

