        SetTint([item], 0xff0000, 0x00ff00, 0x0000ff, 0xffff00);
        expect(item.tintTopLeft).toBe(0xff0000);
        expect(item.tintTopRight).toBe(0x00ff00);
        expect(item.tintBottomLeft).toBe(0x0000ff);
        expect(item.tintBottomRight).toBe(0xffff00);
    });

    it('should pass topLeft and topRight when only two values given', function ()
    {
        var item = makeItem();
        SetTint([item], 0xff0000, 0x00ff00);
        expect(item.tintTopLeft).toBe(0xff0000);
        expect(item.tintTopRight).toBe(0x00ff00);
        expect(item.tintBottomLeft).toBe(undefined);
        expect(item.tintBottomRight).toBe(undefined);
    });

    it('should apply tint to all items in a larger array', function ()
    {
        var items = [makeItem(), makeItem(), makeItem(), makeItem()];
        SetTint(items, 0xaabbcc);
        for (var i = 0; i < items.length; i++)
        {
            expect(items[i].tintTopLeft).toBe(0xaabbcc);
        }
    });

    it('should pass undefined for omitted corner values', function ()
    {
        var item = makeItem();
        SetTint([item], 0xffffff);
        expect(item.tintTopRight).toBe(undefined);
        expect(item.tintBottomLeft).toBe(undefined);
        expect(item.tintBottomRight).toBe(undefined);
    });

    it('should work with a tint value of zero', function ()
    {
        var item = makeItem();
        item.tintTopLeft = 0xff0000;
        SetTint([item], 0x000000);
        expect(item.tintTopLeft).toBe(0x000000);
    });

    it('should work with white tint (0xffffff)', function ()
    {
        var item = makeItem();
        SetTint([item], 0xffffff, 0xffffff, 0xffffff, 0xffffff);
        expect(item.tintTopLeft).toBe(0xffffff);
        expect(item.tintTopRight).toBe(0xffffff);
        expect(item.tintBottomLeft).toBe(0xffffff);
        expect(item.tintBottomRight).toBe(0xffffff);
    });

    it('should call setTint the correct number of times', function ()
    {
        var callCount = 0;
        var items = [];
        for (var i = 0; i < 5; i++)
        {
            var item = makeItem();
            item.setTint = function ()
            {
                callCount++;
            };
            items.push(item);
        }
        SetTint(items, 0xff0000);
        expect(callCount).toBe(5);
    });
});

var SetScrollFactorY = require('../../src/actions/SetScrollFactorY');

describe('Phaser.Actions.SetScrollFactorY', function ()
{
    var items;

    beforeEach(function ()
    {
        items = [
            { scrollFactorY: 0 },
            { scrollFactorY: 0 },
            { scrollFactorY: 0 },
            { scrollFactorY: 0 },
            { scrollFactorY: 0 }
        ];
    });

    it('should set scrollFactorY on all items to the given value', function ()
    {
        SetScrollFactorY(items, 2);

        for (var i = 0; i < items.length; i++)
        {
            expect(items[i].scrollFactorY).toBe(2);
        }
    });

    it('should return the items array', function ()
    {
        var result = SetScrollFactorY(items, 1);

        expect(result).toBe(items);
    });

    it('should set scrollFactorY to zero', function ()
    {
        items[0].scrollFactorY = 5;
        items[1].scrollFactorY = 3;

        SetScrollFactorY(items, 0);

        for (var i = 0; i < items.length; i++)
        {
            expect(items[i].scrollFactorY).toBe(0);
        }
    });

    it('should set scrollFactorY to a negative value', function ()
    {
        SetScrollFactorY(items, -1);

        for (var i = 0; i < items.length; i++)
        {
            expect(items[i].scrollFactorY).toBe(-1);
        }
    });

    it('should set scrollFactorY to a floating point value', function ()
    {
        SetScrollFactorY(items, 0.5);

        for (var i = 0; i < items.length; i++)
        {
            expect(items[i].scrollFactorY).toBeCloseTo(0.5);
        }
    });

    it('should increment scrollFactorY by step for each item', function ()
    {
        SetScrollFactorY(items, 1, 0.5);

        expect(items[0].scrollFactorY).toBeCloseTo(1.0);
        expect(items[1].scrollFactorY).toBeCloseTo(1.5);
        expect(items[2].scrollFactorY).toBeCloseTo(2.0);
        expect(items[3].scrollFactorY).toBeCloseTo(2.5);
        expect(items[4].scrollFactorY).toBeCloseTo(3.0);
    });

    it('should apply a negative step', function ()
    {
        SetScrollFactorY(items, 2, -0.25);

        expect(items[0].scrollFactorY).toBeCloseTo(2.0);
        expect(items[1].scrollFactorY).toBeCloseTo(1.75);
        expect(items[2].scrollFactorY).toBeCloseTo(1.5);
        expect(items[3].scrollFactorY).toBeCloseTo(1.25);
        expect(items[4].scrollFactorY).toBeCloseTo(1.0);
    });

    it('should respect the index offset', function ()
    {
        SetScrollFactorY(items, 3, 0, 2);

        expect(items[0].scrollFactorY).toBe(0);
        expect(items[1].scrollFactorY).toBe(0);
        expect(items[2].scrollFactorY).toBe(3);
        expect(items[3].scrollFactorY).toBe(3);
        expect(items[4].scrollFactorY).toBe(3);
    });

    it('should iterate in reverse when direction is -1', function ()
    {
        SetScrollFactorY(items, 1, 1, 4, -1);

        expect(items[4].scrollFactorY).toBeCloseTo(1);
        expect(items[3].scrollFactorY).toBeCloseTo(2);
        expect(items[2].scrollFactorY).toBeCloseTo(3);
        expect(items[1].scrollFactorY).toBeCloseTo(4);
        expect(items[0].scrollFactorY).toBeCloseTo(5);
    });

    it('should handle an empty array', function ()
    {
        var result = SetScrollFactorY([], 1);

        expect(result).toEqual([]);
    });

    it('should handle a single item array', function ()
    {
        var single = [{ scrollFactorY: 0 }];

        SetScrollFactorY(single, 7);

        expect(single[0].scrollFactorY).toBe(7);
    });

    it('should work with step zero (default)', function ()
    {
        SetScrollFactorY(items, 4, 0);

        for (var i = 0; i < items.length; i++)
        {
            expect(items[i].scrollFactorY).toBe(4);
        }
    });
});

var IncX = require('../../src/actions/IncX');

describe('Phaser.Actions.IncX', function ()
{
    var items;

    beforeEach(function ()
    {
        items = [
            { x: 0 },
            { x: 10 },
            { x: 20 },
            { x: 30 }
        ];
    });

    it('should return the items array', function ()
    {
        var result = IncX(items, 5);
        expect(result).toBe(items);
    });

    it('should add value to x property of each item', function ()
    {
        IncX(items, 5);
        expect(items[0].x).toBe(5);
        expect(items[1].x).toBe(15);
        expect(items[2].x).toBe(25);
        expect(items[3].x).toBe(35);
    });

    it('should add zero value without changing x properties', function ()
    {
        IncX(items, 0);
        expect(items[0].x).toBe(0);
        expect(items[1].x).toBe(10);
        expect(items[2].x).toBe(20);
        expect(items[3].x).toBe(30);
    });

    it('should add a negative value to x properties', function ()
    {
        IncX(items, -5);
        expect(items[0].x).toBe(-5);
        expect(items[1].x).toBe(5);
        expect(items[2].x).toBe(15);
        expect(items[3].x).toBe(25);
    });

    it('should apply step incrementally across items', function ()
    {
        IncX(items, 10, 5);
        expect(items[0].x).toBe(10);
        expect(items[1].x).toBe(25);
        expect(items[2].x).toBe(40);
        expect(items[3].x).toBe(55);
    });

    it('should apply negative step incrementally across items', function ()
    {
        IncX(items, 10, -2);
        expect(items[0].x).toBe(10);
        expect(items[1].x).toBe(18);
        expect(items[2].x).toBe(26);
        expect(items[3].x).toBe(34);
    });

    it('should default step to 0 when not provided', function ()
    {
        IncX(items, 7);
        expect(items[0].x).toBe(7);
        expect(items[1].x).toBe(17);
        expect(items[2].x).toBe(27);
        expect(items[3].x).toBe(37);
    });

    it('should respect the index offset parameter', function ()
    {
        IncX(items, 10, 0, 2);
        expect(items[0].x).toBe(0);
        expect(items[1].x).toBe(10);
        expect(items[2].x).toBe(30);
        expect(items[3].x).toBe(40);
    });

    it('should iterate in reverse when direction is -1', function ()
    {
        IncX(items, 10, 0, 3, -1);
        expect(items[0].x).toBe(10);
        expect(items[1].x).toBe(20);
        expect(items[2].x).toBe(30);
        expect(items[3].x).toBe(40);
    });

    it('should apply step in reverse direction', function ()
    {
        IncX(items, 10, 5, 3, -1);
        expect(items[3].x).toBe(40);
        expect(items[2].x).toBe(35);
        expect(items[1].x).toBe(30);
        expect(items[0].x).toBe(25);
    });

    it('should handle an empty array without error', function ()
    {
        var result = IncX([], 10);
        expect(result).toEqual([]);
    });

    it('should handle a single item array', function ()
    {
        var single = [{ x: 5 }];
        IncX(single, 3);
        expect(single[0].x).toBe(8);
    });

    it('should work with floating point values', function ()
    {
        IncX(items, 1.5);
        expect(items[0].x).toBeCloseTo(1.5);
        expect(items[1].x).toBeCloseTo(11.5);
        expect(items[2].x).toBeCloseTo(21.5);
        expect(items[3].x).toBeCloseTo(31.5);
    });

    it('should work with floating point step values', function ()
    {
        IncX(items, 1, 0.5);
        expect(items[0].x).toBeCloseTo(1);
        expect(items[1].x).toBeCloseTo(11.5);
        expect(items[2].x).toBeCloseTo(22);
        expect(items[3].x).toBeCloseTo(32.5);
    });

    it('should not modify y or other properties', function ()
    {
        var objs = [
            { x: 0, y: 100 },
            { x: 10, y: 200 }
        ];
        IncX(objs, 5);
        expect(objs[0].y).toBe(100);
        expect(objs[1].y).toBe(200);
    });
});
